import {categories,getCategory,calculate,validateRecord} from './rules.js';
import {COURSES,findProfileCourse,createCourseProfile,validateProfile,summarize,createBackup,restoreBackup} from './profile.js';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:2});
const statusLabels={approved:'Aprovada',pending:'Enviada',simulated:'Simulada'};
const viewNames={overview:'Visão geral',activities:'Minhas atividades',categories:'Categorias e regras',simulator:'Simulador',profile:'Meu perfil'};
let records=[],profile=null,db,view='overview',editing=null,existingEvidence=null,search='',statusFilter='',categoryFilter='',toastTimer;
const form=$('#activity-form');
const dialog=$('#activity-dialog');
const storage=new Promise((resolve,reject)=>{const req=indexedDB.open('horas-complementares-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>{db=req.result;resolve(db);};req.onerror=()=>reject(req.error);});
async function readWorkspace(){
  await storage;
  const tx=db.transaction('data');
  const read=key=>new Promise((resolve,reject)=>{
    const req=tx.objectStore('data').get(key);
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error);
  });
  const [savedRecords,savedProfile]=await Promise.all([read('activities'),read('profile')]);
  return {records:savedRecords||[],profile:savedProfile?validateProfile(savedProfile):null};
}
async function persist(next,nextProfile=profile){
  await storage;
  if(nextProfile)nextProfile=validateProfile(nextProfile);
  return new Promise((resolve,reject)=>{
    const tx=db.transaction('data','readwrite');
    tx.objectStore('data').put(next,'activities');
    tx.objectStore('data').put(nextProfile,'profile');
    tx.oncomplete=()=>{records=next;profile=nextProfile;resolve();};
    tx.onerror=()=>reject(Error('Não foi possível salvar. Verifique o espaço disponível no navegador.'));
    tx.onabort=()=>reject(Error('O navegador não conseguiu salvar os dados.'));
  });
}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function heading(title,description,action=true){return `<div class="page-heading"><div><span class="eyebrow">SUAS ATIVIDADES COMPLEMENTARES</span><h1>${title}</h1><p>${description}</p></div>${action?'<button class="button primary" data-action="new"><span>＋</span> Adicionar atividade</button>':''}</div>`;}
function badge(status){return `<span class="status ${status}">● ${statusLabels[status]}</span>`;}
function empty(title='Sua jornada começa aqui',description='Cadastre sua primeira atividade e veja suas horas ganharem forma.'){return `<div class="empty"><div class="empty-icon">▤</div><h3>${title}</h3><p>${description}</p><button class="button secondary" data-action="new">＋ Adicionar atividade</button></div>`;}
function activityRow(r,calc){return `<div class="activity-row"><span class="activity-icon">▤</span><div class="activity-info"><button class="text-button activity-title" data-action="detail" data-id="${esc(r.id)}">${esc(r.title)}</button><small>${esc(getCategory(r.category).name)}</small></div><div class="activity-hours">${fmt(calc.results.get(r.id).credited)} h<small>${badge(r.status)}</small></div></div>`;}
function renderOverview(){const c=summarize(records,profile),a=c.totals.approved,{remaining}=c;const usedCats=categories.filter(cat=>c.used[cat.id]>0);const shown=(usedCats.length?usedCats:[getCategory('estagio'),getCategory('cursos'),getCategory('congressos'),getCategory('extensao')]).slice(0,4);return heading(`Olá, ${esc(profile.name.split(/\s+/)[0])}. Cada atividade conta.`,`Acompanhe sua jornada em ${esc(profile.course)} até as ${fmt(profile.goal)} horas.`)+`<section class="hero journey-guide" aria-labelledby="journey-title">
  <div class="journey-heading"><span class="eyebrow">SEU CAMINHO ATÉ A CONCLUSÃO</span><h2 id="journey-title">Da simulação à aprovação, passo a passo.</h2><p>Saiba o que fazer em cada etapa das suas atividades complementares.</p></div>
  <ol class="journey-steps">
    <li><span class="journey-number">Passo 1</span><h3><a href="#simulator" data-action="navigate" data-view="simulator">Simular <span aria-hidden="true">↗</span></a></h3><p>Confira quanto sua atividade pode valer e quais documentos são exigidos.</p></li>
    <li><span class="journey-number">Passo 2</span><h3><a href="#activities" data-action="navigate" data-view="activities">Verificar suas atividades <span aria-hidden="true">↗</span></a></h3><p>Revise os registros, os comprovantes e os limites de cada categoria antes de enviar.</p></li>
    <li><span class="journey-number">Passo 3</span><h3>Abrir solicitação no Lyceum</h3><p>Acesse o Lyceum da CESAR School e abra sua solicitação com os comprovantes. Esta etapa é feita fora do Horas.</p></li>
    <li><span class="journey-number">Passo 4</span><h3><a href="#activities" data-action="navigate" data-view="activities" data-reset-filters="true">Atualizar status das atividades <span aria-hidden="true">↗</span></a></h3><p>Após confirmar a aprovação no Lyceum, abra Minhas atividades, edite a atividade simulada ou enviada e altere sua situação para Aprovada.</p></li>
  </ol>
</section><section class="academic-disclaimer" aria-labelledby="academic-disclaimer-title"><span class="disclaimer-icon" aria-hidden="true">ⓘ</span><div><h2 id="academic-disclaimer-title">Aviso de uso acadêmico e não comercial</h2><p>Projeto acadêmico independente, desenvolvido para apoiar estudantes da CESAR School no planejamento e acompanhamento de atividades complementares. Destina-se exclusivamente a fins educacionais, sem finalidade comercial. Não constitui uma plataforma oficial da instituição e não substitui o regulamento vigente nem a análise e a validação das atividades pela coordenação.</p><p class="disclaimer-reference"><strong>Regras atuais - 2026.2 :</strong> <a href="https://drive.google.com/file/d/1fpUxnOsYP123YRaCTnLq7jALZRvU9zox/view?usp=drive_link/" target="_blank" rel="noopener noreferrer">Manual do Estudante - Páginas 34 e 35<span class="optional"> ↗</span></a></p></div></section><section class="stats" aria-label="Resumo das horas"><article class="stat"><div class="stat-head"><span class="stat-icon">✓</span> Horas aprovadas</div><div class="stat-value">${fmt(a)}<span>h</span></div><small>Aprovação informada por você</small></article><article class="stat"><div class="stat-head"><span class="stat-icon">◷</span> Aguardando avaliação</div><div class="stat-value">${fmt(c.totals.pending)}<span>h</span></div><small>Estimativa das atividades enviadas</small></article><article class="stat"><div class="stat-head"><span class="stat-icon">◇</span> Horas simuladas</div><div class="stat-value">${fmt(c.totals.simulated)}<span>h</span></div><small>Possibilidades para seu planejamento</small></article><article class="stat"><div class="stat-head"><span class="stat-icon">⚑</span> Falta para sua meta</div><div class="stat-value">${fmt(remaining)}<span>h</span></div><small>${fmt(Math.min(a/profile.goal*100,100))}% da meta concluída</small></article></section><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Atividades recentes</h2><p>Seus próximos passos e suas conquistas.</p></div><button class="text-button" data-action="navigate" data-view="activities">Ver todas ↗</button></div>${records.length?[...records].reverse().slice(0,4).map(r=>activityRow(r,c)).join(''):empty()}</section><section class="panel"><div class="panel-heading"><div><h2>Horas por categoria</h2><p>Ocupação prevista dos limites do manual.</p></div><span style="color:#9ba2aa">▦</span></div><div class="category-bars">${shown.map(cat=>`<div class="category-bar"><div class="bar-label">${esc(cat.name)}<span>${fmt(c.used[cat.id]||0)} / ${cat.cap} h</span></div><div class="track"><span style="width:${(c.used[cat.id]||0)/cat.cap*100}%"></span></div></div>`).join('')}<button class="text-button" data-action="navigate" data-view="categories">Explorar as 24 categorias ↗</button></div></section></div>`;}
function renderActivities(){return heading('Minha coleção de conquistas.','Registre, simule e acompanhe cada atividade em um só lugar.')+`<div class="toolbar"><label class="search" style="margin:0"><span class="optional" hidden>Buscar atividades</span><input id="activity-search" aria-label="Buscar atividades" placeholder="Buscar uma atividade..." value="${esc(search)}" style="margin:0"></label><select id="status-filter" aria-label="Filtrar por situação"><option value="">Todas as situações</option>${Object.entries(statusLabels).map(([id,name])=>`<option value="${id}" ${statusFilter===id?'selected':''}>${name}</option>`).join('')}</select><select id="category-filter" aria-label="Filtrar por categoria"><option value="">Todas as categorias</option>${categories.map(c=>`<option value="${c.id}" ${categoryFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="panel" id="activities-list">${activitiesTable()}</div><div class="data-actions"><button class="backup-button" data-action="export">↓ Exportar backup completo</button><button class="backup-button" data-action="import">↑ Importar backup</button><span>Os comprovantes ficam neste navegador. Guarde uma cópia de segurança.</span></div>`;}
function activitiesTable(){const c=calculate(records);const filtered=records.filter(r=>(!statusFilter||r.status===statusFilter)&&(!categoryFilter||r.category===categoryFilter)&&`${r.title} ${getCategory(r.category).name}`.toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR'))).reverse();if(!records.length)return empty('Sua primeira conquista está por vir.','Um curso, um estágio ou um evento: comece pelo que você já tem.');if(!filtered.length)return '<div class="empty"><h3>Nenhuma atividade encontrada</h3><p>Tente outro termo ou altere os filtros.</p></div>';return `<div class="table-wrap"><table><thead><tr><th>ATIVIDADE</th><th>SITUAÇÃO</th><th>APROVEITAMENTO</th><th>AÇÕES</th></tr></thead><tbody>${filtered.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${esc(getCategory(r.category).name)} · ${r.date.split('-').reverse().join('/')}</small></td><td>${badge(r.status)}</td><td><strong>${fmt(c.results.get(r.id).credited)} h</strong>${c.results.get(r.id).excluded?`<small>${fmt(c.results.get(r.id).excluded)} h fora do limite</small>`:''}</td><td><div class="actions"><button class="icon-button" data-action="detail" data-id="${esc(r.id)}" aria-label="Ver ${esc(r.title)}" title="Ver detalhes">↗</button><button class="icon-button" data-action="edit" data-id="${esc(r.id)}" aria-label="Editar ${esc(r.title)}" title="Editar">✎</button><button class="icon-button danger" data-action="delete" data-id="${esc(r.id)}" aria-label="Excluir ${esc(r.title)}" title="Excluir">×</button></div></td></tr>`).join('')}</tbody></table></div>`;}
function renderCategories(){const c=calculate(records);return heading('Encontre seu próximo caminho.','24 categorias, seus limites e o que você precisa comprovar.',false)+`<div class="notice">Regras da CESAR School, transcritas do manual fornecido para este projeto. Alterar o curso ou a meta do perfil não altera estes limites. Confira se este regulamento se aplica ao seu curso. Nos casos sem conversão explícita, a simulação usa as horas comprovadas, sujeitas à análise da faculdade. Confirme eventuais regras gerais e a versão do manual antes da entrega.</div><div class="toolbar"><label class="search" style="margin:0"><input id="category-search" aria-label="Buscar categoria" placeholder="Buscar categoria ou atividade..." style="margin:0"></label></div><div class="categories-grid" id="category-grid">${categories.map(cat=>`<article class="category-card" data-category-text="${esc((cat.name+' '+cat.rule).toLocaleLowerCase('pt-BR'))}"><div class="category-top"><span>▦ Categoria</span><strong>${cat.cap} h <span class="optional">máximo</span></strong></div><h3>${esc(cat.name)}</h3><p>${esc(cat.rule)}</p><details><summary>Ver comprovação e condições</summary><p>${esc(cat.proof)}</p>${cat.checks.length?`<ul class="checklist">${cat.checks.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}</details><div class="track"><span style="width:${(c.used[cat.id]||0)/cat.cap*100}%"></span></div><div class="category-meta"><span>${fmt(c.used[cat.id]||0)} h previstas</span><span>${fmt(Math.max(0,cat.cap-(c.used[cat.id]||0)))} h disponíveis</span></div><button class="text-button" data-action="new" data-category="${cat.id}">Simular nesta categoria ↗</button></article>`).join('')}</div><p id="no-categories" class="empty" hidden>Nenhuma categoria encontrada.</p>`;}
function renderSimulator(){return heading('Antes de enviar, experimente.','Entenda o que sua próxima atividade pode acrescentar à sua jornada.',false)+`<section class="panel simulator-hero"><div><span class="eyebrow">PLANEJE COM MAIS CLAREZA</span><h2>Seu certificado tem horas.<br>Vamos descobrir quantas contam?</h2><p>O simulador considera a regra da categoria e as atividades que você já cadastrou. A estimativa vem com o cálculo e os requisitos para conferir.</p><button class="button primary" data-action="new">◇ Fazer uma simulação <span>↗</span></button></div><div class="steps"><div class="step"><span>01</span><div><h3>Escolha a categoria</h3><p>Consulte o enquadramento da atividade no manual.</p></div></div><div class="step"><span>02</span><div><h3>Informe a participação</h3><p>Horas, meses ou quantidade, conforme a regra.</p></div></div><div class="step"><span>03</span><div><h3>Veja o aproveitamento</h3><p>Confira a conversão, os limites e os documentos.</p></div></div></div></section><section class="example"><h3>Na prática: um workshop CESAR de 8 horas</h3><p>A conversão gera 4 horas complementares. Se você já tem 18 das 20 horas permitidas nessa categoria, o aproveitamento adicional será de 2 horas.</p></section><div class="tip"><span>◇</span><div><strong>Uma estimativa para se organizar.</strong><p>A simulação não aprova certificados e não substitui a avaliação da faculdade. Concursos e outras atividades têm análise específica.</p></div></div>`;}
function renderProfile(){
  const first=!profile;
  const selectedCourse=findProfileCourse(profile);
  const groups=[...new Set(COURSES.map(course=>course.group))];
  return `<section class="profile-page ${first?'first-access':''}">
    <div class="profile-intro"><span class="eyebrow">${first?'BEM-VINDO AO HORAS':'SEU ESPAÇO, SUAS METAS'}</span>
      <h1>${first?'Vamos conhecer sua jornada?':'Meu perfil'}</h1>
      <p>${first?'Informe seu nome e selecione seu curso. A meta de horas será preenchida automaticamente.':'Atualize seu nome ou selecione outro curso para ajustar automaticamente a meta de horas.'}</p>
    </div>
    <form id="profile-form" class="panel profile-form">
      <label>Nome do aluno<input name="studentName" autocomplete="name" required maxlength="100" placeholder="Como você se chama?" value="${esc(profile?.name||'')}"></label>
      <label>Curso<select name="course" required aria-describedby="goal-help"><option value="" disabled ${!selectedCourse?'selected':''}>Selecione seu curso</option>${groups.map(group=>`<optgroup label="${esc(group)}">${COURSES.filter(course=>course.group===group).map(course=>`<option value="${course.id}" ${selectedCourse?.id===course.id?'selected':''}>${esc(course.name)} — ${course.goal} horas</option>`).join('')}</optgroup>`).join('')}</select></label>
      <label>Horas complementares exigidas<input name="goal" type="number" readonly value="${selectedCourse?.goal??''}" placeholder="Selecione um curso" aria-describedby="goal-help"></label>
      <p id="goal-help" class="field-help">A meta é definida pelo curso selecionado: bacharelados exigem 120 horas e tecnológicos, 90 horas. Ao trocar de curso, suas atividades são preservadas.</p>
      ${profile&&!profile.courseId?`<p class="profile-preserved">Perfil anterior: ${esc(profile.course)} · ${fmt(profile.goal)} horas. ${selectedCourse?'Ao salvar, a meta será atualizada conforme o curso da lista.':'Selecione seu curso para atualizar o perfil.'}</p>`:''}
      <div class="notice"><strong>Regulamento utilizado: CESAR School</strong><br>As 24 categorias e seus limites seguem as tabelas do manual fornecido para este projeto. Confirme se essas regras se aplicam ao seu curso. A meta acompanha o curso selecionado; os limites das categorias continuam seguindo esse manual.</div>
      ${records.length?`<p class="profile-preserved">✓ Suas ${records.length} atividades já cadastradas serão mantidas.</p>`:''}
      <p id="profile-error" class="error" role="alert"></p>
      <div class="profile-form-actions"><button class="button primary" type="submit">${first?'Começar minha jornada':'Salvar perfil'} <span>↗</span></button>${first?'<button class="text-button" type="button" data-action="import">Já tenho um backup</button>':'<a href="#overview" class="button secondary">Voltar ao painel</a>'}</div>
    </form>
    <p class="profile-privacy">Seu perfil, suas atividades e seus comprovantes ficam neste navegador. Este perfil não cria uma conta nem sincroniza dados entre dispositivos.</p>
  </section>`;
}
function render(){
  view=location.hash.slice(1)||'overview';
  if(!Object.hasOwn(viewNames,view))view='overview';
  if(!profile)view='profile';
  document.body.classList.toggle('onboarding',!profile);
  $('#breadcrumb').textContent=profile?viewNames[view]:'Configurar meu perfil';
  $('#activity-count').textContent=records.length;
  $('#workspace-description').textContent=profile?`${profile.course} · ${fmt(profile.goal)} horas`:'Configure seu perfil';
  $('#student-name').textContent=profile?.name||'Meu espaço';
  $('#student-course').textContent=profile?.course||'Atividades complementares';
  const names=(profile?.name||'Meu espaço').split(/\s+/);
  $('#student-initials').textContent=(names[0][0]+(names.length>1?names.at(-1)[0]:'')).toUpperCase();
  document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));
  $('#main').innerHTML=({overview:renderOverview,activities:renderActivities,categories:renderCategories,simulator:renderSimulator,profile:renderProfile})[view]();
}
const amountLabels={hours:'Horas da atividade',months:'Meses de participação',units:'Quantidade de participações / publicações',semesters:'Quantidade de monitorias semestrais',review:'Horas estimadas para esta participação',fixed:'Crédito previsto (horas)'};
function setCategory(checks=[]){const c=getCategory(form.elements.category.value);$('#form-rule').textContent=c.rule;$('#proof-text').textContent=c.proof;const label=$('#amount-label');label.firstChild.textContent=amountLabels[c.mode];const amount=form.elements.amount;amount.disabled=c.mode==='fixed';amount.step=['units','semesters','months'].includes(c.mode)?'1':'0.01';amount.min=['units','semesters','months'].includes(c.mode)?'1':'0.01';amount.max=c.mode==='review'?'25':'100000';if(c.mode==='fixed')amount.value=c.rate;$('#form-checks').innerHTML=c.checks.map((s,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${checks[i]?'checked':''}>${esc(s)}</label>`).join('');preview();}
function draft(){return {id:editing||'__preview__',title:form.elements.title.value.trim(),category:form.elements.category.value,amount:Number(form.elements.amount.value),date:form.elements.date.value,status:form.elements.status.value,notes:form.elements.notes.value.trim(),checks:[...$('#form-checks').querySelectorAll('input')].map(input=>input.checked),evidence:existingEvidence};}
function preview(){try{const r=draft();const before=calculate(records);const next=records.map(item=>item.id===editing?r:item);if(!editing)next.push(r);const c=calculate(next),result=c.results.get(r.id),cat=getCategory(r.category);const incomplete=r.checks.some(v=>!v);const hasEvidence=!!(existingEvidence||form.elements.evidence.files[0]);$('#form-calculation').innerHTML=`<span>APROVEITAMENTO PREVISTO</span><br><strong>${fmt(result.credited)} h</strong> <span>de ${fmt(result.base)} h calculadas</span><small>${result.excluded?`${fmt(result.excluded)} h excedem o limite de ${cat.cap} h da categoria.`:`Dentro do limite de ${cat.cap} h da categoria.`} ${cat.mode==='months'&&r.amount<6?'São necessários pelo menos 6 meses completos.':''}</small><small>Previsão total: ${fmt(c.total)} / ${fmt(profile.goal)} h · faltariam ${fmt(Math.max(0,Math.round((profile.goal-c.total)*100)/100))} h.</small>${!editing&&c.total-before.total<result.credited?'<small>Esta atividade ocupa o lugar de horas pendentes ou simuladas por ter prioridade maior.</small>':''}<small>${incomplete||!hasEvidence?'⚑ Há requisitos ou comprovantes a conferir.':'✓ Requisitos marcados por você. A conferência final é da faculdade.'}${['outras','competicao'].includes(cat.id)?' Esta categoria depende de avaliação específica.':''}</small>`;$('#form-error').textContent='';}catch(error){$('#form-calculation').textContent=error.message;}}
function openForm(category,record){editing=record?.id||null;existingEvidence=record?.evidence||null;form.reset();form.elements.category.innerHTML=categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');form.elements.category.value=record?.category||category||'cursos';form.elements.title.value=record?.title||'';form.elements.date.value=record?.date||new Date().toLocaleDateString('en-CA');form.elements.amount.value=record?.amount||1;form.elements.status.value=record?.status||'simulated';form.elements.notes.value=record?.notes||'';form.elements.approvalConfirmed.checked=record?.status==='approved';$('#approval-confirm').hidden=form.elements.status.value!=='approved';form.elements.approvalConfirmed.required=form.elements.status.value==='approved';$('#modal-title').textContent=record?'Editar atividade':'Adicionar atividade';$('#existing-evidence').innerHTML=existingEvidence?`<p class="field-help">Arquivo atual: ${esc(existingEvidence.name)} <button type="button" class="text-button" id="remove-evidence">Remover</button></p>`:'';setCategory(record?.checks||[]);$('#form-error').textContent='';dialog.showModal();}
function evidenceFromFile(file){return new Promise((resolve,reject)=>{if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type)){reject(Error('Use um PDF ou uma imagem PNG, JPG ou WebP.'));return;}if(file.size>5*1024*1024){reject(Error('O comprovante deve ter no máximo 5 MB.'));return;}const reader=new FileReader();reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.onload=()=>resolve({name:file.name,type:file.type,data:reader.result});reader.readAsDataURL(file);});}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadEvidence(id){const r=records.find(r=>r.id===id);if(!r?.evidence)return;const [header,body]=r.evidence.data.split(',');const binary=atob(body),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));download(new Blob([bytes],{type:r.evidence.type}),r.evidence.name);}
function showDetails(id){const r=records.find(r=>r.id===id);if(!r)return;const c=getCategory(r.category),result=calculate(records).results.get(id);$('#detail-content').innerHTML=`<h2>${esc(r.title)}</h2>${badge(r.status)}<div class="detail-line"><small>Categoria</small>${esc(c.name)}</div><div class="detail-line"><small>Aproveitamento atual</small>${fmt(result.credited)} h de ${fmt(result.base)} h calculadas · limite de ${c.cap} h</div><div class="detail-line"><small>Regra</small>${esc(c.rule)}</div><div class="detail-line"><small>Data de conclusão</small>${r.date.split('-').reverse().join('/')}</div><div class="detail-line"><small>Comprovação exigida</small>${esc(c.proof)}</div>${c.checks.length?`<ul class="checklist">${c.checks.map((s,i)=>`<li>${r.checks[i]?'✓':'Pendente:'} ${esc(s)}</li>`).join('')}</ul>`:''}<div class="detail-line"><small>Comprovante</small>${r.evidence?`<button class="text-button" data-action="evidence" data-id="${esc(id)}">↓ ${esc(r.evidence.name)}</button>`:'Nenhum comprovante anexado.'}</div>${r.notes?`<div class="detail-line"><small>Observações</small><span style="white-space:pre-wrap">${esc(r.notes)}</span></div>`:''}<p class="field-help" style="margin-top:16px">Situação informada por você. Sem integração com a faculdade.</p><button class="button secondary" data-action="detail-edit" data-id="${esc(id)}">Editar atividade</button>`;$('#detail-dialog').showModal();}
async function exportBackup(){
  try{
    const data=createBackup(records,profile);
    download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`horas-backup-${new Date().toLocaleDateString('en-CA')}.json`);
    toast('Backup exportado com perfil, atividades e comprovantes.');
  }catch(error){toast(error.message);}
}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const {action,id,category}=b.dataset;try{if(action==='navigate'){if(b.dataset.view==='activities'){statusFilter=b.dataset.status||'';if(b.dataset.resetFilters==='true'){search='';categoryFilter='';}}if(location.hash==='#'+b.dataset.view)render();else location.hash=b.dataset.view;}if(action==='new')openForm(category);if(action==='edit')openForm(null,records.find(r=>r.id===id));if(action==='detail')showDetails(id);if(action==='detail-edit'){$('#detail-dialog').close();openForm(null,records.find(r=>r.id===id));}if(action==='delete'){const r=records.find(r=>r.id===id);if(r&&confirm(`Excluir “${r.title}” e o comprovante? Esta ação não pode ser desfeita.`)){await persist(records.filter(r=>r.id!==id));render();toast('Atividade excluída. Os saldos foram recalculados.');}}if(action==='export')await exportBackup();if(action==='import')$('#import-file').click();if(action==='evidence')downloadEvidence(id);}catch(error){toast(error.message);}});
document.addEventListener('input',event=>{if(event.target.id==='activity-search'){search=event.target.value;$('#activities-list').innerHTML=activitiesTable();}if(event.target.id==='category-search'){const term=event.target.value.toLocaleLowerCase('pt-BR');let matches=0;document.querySelectorAll('[data-category-text]').forEach(card=>{card.hidden=!card.dataset.categoryText.includes(term);if(!card.hidden)matches++;});$('#no-categories').hidden=matches>0;}});
document.addEventListener('change',event=>{if(event.target.id==='status-filter'){statusFilter=event.target.value;$('#activities-list').innerHTML=activitiesTable();}if(event.target.id==='category-filter'){categoryFilter=event.target.value;$('#activities-list').innerHTML=activitiesTable();}});
form.elements.category.addEventListener('change',()=>{form.elements.amount.value=1;setCategory();});form.addEventListener('input',preview);form.addEventListener('change',()=>{const approved=form.elements.status.value==='approved';$('#approval-confirm').hidden=!approved;form.elements.approvalConfirmed.required=approved;preview();});form.addEventListener('click',event=>{if(event.target.id==='remove-evidence'){existingEvidence=null;$('#existing-evidence').innerHTML='';preview();}});
form.addEventListener('submit',async event=>{event.preventDefault();const save=$('#save-activity');save.disabled=true;try{const r=draft();r.id=editing||crypto.randomUUID();const file=form.elements.evidence.files[0];if(file)r.evidence=await evidenceFromFile(file);validateRecord(r);const next=editing?records.map(item=>item.id===editing?r:item):[...records,r];await persist(next);dialog.close();render();toast(editing?'Atividade atualizada.':'Atividade salva. Mais um passo na sua jornada!');}catch(error){$('#form-error').textContent=error.message;}finally{save.disabled=false;}});
$('#close-modal').onclick=$('#cancel-modal').onclick=()=>dialog.close();$('#close-details').onclick=()=>$('#detail-dialog').close();$('#export-sidebar').onclick=exportBackup;
$('#import-file').addEventListener('change',async event=>{
  const file=event.target.files[0];if(!file)return;
  try{
    if(file.size>100*1024*1024)throw Error('O backup excede o limite de 100 MB.');
    const data=JSON.parse(await file.text());
    const next=restoreBackup(data,profile);
    const detail=data.version===2?`O perfil será restaurado para ${next.profile.name}, ${next.profile.course}, com meta de ${fmt(next.profile.goal)} horas.`:profile?'Seu perfil e sua meta atuais serão mantidos.':'Depois, preencha seu nome, curso e meta para continuar.';
    if(confirm(`Restaurar ${next.records.length} atividades? O backup substituirá seus registros atuais. ${detail} Exporte uma cópia antes de continuar.`)){
      await persist(next.records,next.profile);
      render();toast('Backup restaurado com sucesso.');
    }
  }catch(error){toast(error instanceof SyntaxError?'O arquivo não contém um backup JSON válido.':error.message);}
  finally{event.target.value='';}
});
document.addEventListener('change',event=>{
  if(event.target.name!=='course'||event.target.form?.id!=='profile-form')return;
  const course=COURSES.find(course=>course.id===event.target.value);
  event.target.form.elements.goal.value=course?.goal??'';
});
document.addEventListener('submit',async event=>{
  if(event.target.id!=='profile-form')return;
  event.preventDefault();
  const profileForm=event.target,button=profileForm.querySelector('[type="submit"]');
  button.disabled=true;
  try{
    const next=createCourseProfile(profileForm.elements.studentName.value,profileForm.elements.course.value);
    const wasFirst=!profile;
    await persist(records,next);
    if(wasFirst&&location.hash!=='#overview')location.hash='overview';
    render();toast(wasFirst?'Seu espaço está pronto. Vamos começar!':'Perfil atualizado. Sua meta foi recalculada.');
  }catch(error){$('#profile-error').textContent=error.message;button.disabled=false;}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});
$('#main').innerHTML='<div class="loading">Preparando seu espaço…</div>';
try{const saved=await readWorkspace();records=saved.records;profile=saved.profile;records.forEach(validateRecord);render();}catch(error){$('#main').innerHTML=`<div class="notice"><h2>Não foi possível abrir seus dados</h2><p>${esc(error.message)} Verifique se o armazenamento do navegador está habilitado e tente novamente. Nenhum registro foi alterado.</p></div>`;}
